106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        String address = normalizeAddress(ownerFieldsDto.getAddress());
110	        List<String> missingFields = new ArrayList<>();
111	        if (isBlank(ownerFieldsDto.getFirstName())) {
112	            missingFields.add("firstName");
113	        }
114	        if (isBlank(ownerFieldsDto.getLastName())) {
115	            missingFields.add("lastName");
116	        }
117	        if (isBlank(address)) {
118	            missingFields.add("address");
119	        }
120	        if (isBlank(ownerFieldsDto.getCity())) {
121	            missingFields.add("city");
122	        }
123	        if (isBlank(ownerFieldsDto.getTelephone())) {
124	            missingFields.add("telephone");
125	        }
126	        if (!missingFields.isEmpty()) {
127	            throw new MissingOwnerFieldsException(missingFields);
128	        }
129	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
130	        if (isTelephoneInUse(telephone)) {
131	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
132	        }
133	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
134	        if (!sharesHousehold
135	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
136	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
137	        }
138	        if (isCityAtCapacity(ownerFieldsDto.getCity())) {
139	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
140	        }
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        owner.setAddress(address);
144	        owner.setTelephone(telephone);
145	        if (owner.getRegistrationDate() == null) {
146	            owner.setRegistrationDate(LocalDate.now());
147	        }
148	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
149	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
150	        if (sharesHousehold) {
151	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
152	        }
153	        this.clinicService.saveOwner(owner);
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
