252	
253	    private static boolean isBlank(String value) {
254	        return value == null || value.isBlank();
255	    }
256	
257	    /**
258	     * Normalizes a street address into the canonical form stored on and returned for a newly
259	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
260	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
261	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
262	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
263	     * value is what gets persisted, echoed back, and used for every address comparison (household
264	     * duplicate detection and the shared household identifier).
265	     *
266	     * @param rawAddress the address value as supplied by the client
267	     * @return the normalized address (possibly empty, never {@code null})
268	     */
269	    private static String normalizeAddress(String rawAddress) {
270	        if (rawAddress == null) {
271	            return "";
272	        }
273	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
274	        if (collapsed.isEmpty()) {
275	            return "";
276	        }
277	        String[] tokens = collapsed.split(" ");
278	        StringBuilder sb = new StringBuilder(collapsed.length());
279	        for (int i = 0; i < tokens.length; i++) {
280	            String token = tokens[i];
281	            switch (token) {
282	                case "ST" -> token = "STREET";
283	                case "RD" -> token = "ROAD";
284	                case "AVE" -> token = "AVENUE";
285	                default -> { }
286	            }
287	            if (i > 0) {
288	                sb.append(' ');
289	            }
290	            sb.append(token);
291	        }
292	        return sb.toString();
293	    }
294	
295	    /**
296	     * Builds the customer code assigned to a newly created owner. The code is formatted
297	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
298	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
299	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
300	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
301	     *
302	     * @param city the city of the owner being created
303	     * @param lastName the last name of the owner being created
304	     * @return the customer code to assign
305	     */
306	    private String nextCustomerCode(String city, String lastName) {
307	        String city3 = letterPrefix3(city);
308	        String last3 = letterPrefix3(lastName);
309	        String normalizedCity = normalizeIdentity(city);
310	        long sequence = this.clinicService.findAllOwners().stream()
311	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
312	            .count() + 1L;
313	        return String.format("%s-%s-%04d", city3, last3, sequence);
314	    }
315	
316	    /**
317	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
318	     * characters. Values with fewer than three letters yield a shorter prefix.
319	     *
320	     * @param value the source text
321	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
322	     */
323	    private static String letterPrefix3(String value) {
324	        StringBuilder prefix = new StringBuilder(3);
325	        if (value != null) {
326	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
327	                char c = value.charAt(i);
328	                if (Character.isLetter(c)) {
329	                    prefix.append(Character.toUpperCase(c));
330	                }
331	            }
332	        }
333	        return prefix.toString();
334	    }
335	
336	    /**
337	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
338	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
339	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
340	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
341	     *
342	     * @param rawTelephone the telephone value as supplied by the client
343	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
344	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
345	     */
346	    private static String normalizeTelephone(String rawTelephone) {
347	        if (rawTelephone == null) {
348	            throw new InvalidTelephoneException(rawTelephone);
349	        }
350	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
351	        String e164;
352	        if (cleaned.startsWith("+")) {
353	            String digits = cleaned.substring(1);
354	            if (!digits.matches("[0-9]+")) {
355	                throw new InvalidTelephoneException(rawTelephone);
356	            }
357	            e164 = "+" + digits;
358	        } else {
359	            if (!cleaned.matches("[0-9]+")) {
360	                throw new InvalidTelephoneException(rawTelephone);
361	            }
362	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
363	            e164 = "+61" + national;
364	        }
365	        int digitCount = e164.length() - 1;
366	        if (digitCount < 8 || digitCount > 15) {
367	            throw new InvalidTelephoneException(rawTelephone);
368	        }
369	        return e164;
370	    }
371	
372	    /**
373	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
374	     * telephones are themselves E.164, so the values are compared directly.
375	     *
376	     * @param e164Telephone the E.164 telephone of the owner being created
377	     * @return {@code true} if another owner already has the same E.164 telephone
378	     */
379	    private boolean isTelephoneInUse(String e164Telephone) {
380	        return this.clinicService.findAllOwners().stream()
381	            .map(Owner::getTelephone)
382	            .filter(existing -> existing != null)
383	            .anyMatch(e164Telephone::equals);
384	    }
385	
386	    /**
387	     * Determines whether any existing owner already shares a household with the owner being created,
388	     * i.e. has both the same last name and the same address. Both fields are compared
389	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
390	     *
391	     * @param lastName the last name of the owner being created
392	     * @param address the address of the owner being created
393	     * @return {@code true} if another owner already has the same last name and address
394	     */
395	    private boolean isHouseholdInUse(String lastName, String address) {
396	        String normalizedLastName = normalizeIdentity(lastName);
397	        String normalizedAddress = normalizeIdentity(address);
398	        return this.clinicService.findAllOwners().stream()
399	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
400	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
401	    }
402	
403	    /**
404	     * Counts how many existing owners already share the given first name and last name with the
405	     * owner being created. Both names are compared case-insensitively (after trimming and
406	     * collapsing runs of whitespace). The count reflects the state before the new owner is
407	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
408	     *
409	     * @param firstName the first name of the owner being created
410	     * @param lastName the last name of the owner being created
411	     * @return the number of existing owners sharing the same first and last name
412	     */
413	    private int namesakeCount(String firstName, String lastName) {
414	        String normalizedFirstName = normalizeIdentity(firstName);
415	        String normalizedLastName = normalizeIdentity(lastName);
416	        return (int) this.clinicService.findAllOwners().stream()
417	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
418	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
419	            .count();
420	    }
421	
422	    /**
423	     * The maximum number of owners permitted in a single city. Once a city already contains this
424	     * many owners it is considered full and no further owners may be created there.
425	     */
426	    private static final int CITY_CAPACITY = 50;
427	
428	    /**
429	     * Determines whether the given city has already reached its capacity, i.e. already contains
430	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
431	     * collapsing runs of whitespace to a single space and trimming.
432	     *
433	     * @param city the city of the owner being created
434	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
435	     */
436	    private boolean isCityAtCapacity(String city) {
437	        String normalizedCity = normalizeIdentity(city);
438	        long count = this.clinicService.findAllOwners().stream()
439	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
440	            .count();
441	        return count >= CITY_CAPACITY;
442	    }
443	
444	    /**
445	     * Assigns the owner being created to the household identified by the given last name and
446	     * address and returns the household's stable shared identifier. The identifier is derived
447	     * deterministically from the normalized last name and address, so every member of the same
448	     * household resolves to the same value regardless of creation order. Any existing member that
449	     * does not yet carry the identifier is back-filled so all household members share it.
450	     *
451	     * @param lastName the last name of the owner being created
452	     * @param address the address of the owner being created
453	     * @return the stable household identifier shared by all members of the household
454	     */
455	    private String joinHousehold(String lastName, String address) {
456	        String householdId = householdIdFor(lastName, address);
457	        String normalizedLastName = normalizeIdentity(lastName);
458	        String normalizedAddress = normalizeIdentity(address);
459	        for (Owner existing : this.clinicService.findAllOwners()) {
460	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
461	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
462	                && !householdId.equals(existing.getHouseholdId())) {
463	                existing.setHouseholdId(householdId);
464	                this.clinicService.saveOwner(existing);
465	            }
466	        }
467	        return householdId;
468	    }
469	
470	    /**
471	     * Derives the stable household identifier for a given last name and address. The value is the
472	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
473	     * address, so it is stable across calls and identical for every member of the household.
474	     *
475	     * @param lastName the last name of the household
476	     * @param address the address of the household
477	     * @return the stable household identifier
478	     */
479	    private static String householdIdFor(String lastName, String address) {
480	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
481	        try {
482	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
483	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
484	            StringBuilder sb = new StringBuilder(digest.length * 2);
485	            for (byte b : digest) {
486	                sb.append(String.format("%02x", b));
487	            }
488	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
489	        }
490	        catch (java.security.NoSuchAlgorithmException e) {
491	            throw new IllegalStateException("SHA-256 not available", e);
492	        }
493	    }
494	
495	    /**
496	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
497	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
498	     * single space, and the result is lower-cased.
499	     *
500	     * @param value the raw field value
501	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
502	     */
503	    private static String normalizeIdentity(String value) {
504	        if (value == null) {
505	            return "";
506	        }
507	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
508	    }
509	}
